changeSet.sql:
INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'integration.webhook.allow-http', 'true', 'BOOLEAN', 'Integration-client webhook callback URL may be plain http://. Activate for dev/test only; production should stay https.', false, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'integration.webhook.allow-http');

INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'integration.webhook.allow-private-network', 'true', 'BOOLEAN', 'Webhook callback URL may resolve to a private network (10.x, 172.16-31.x, 192.168.x, CGNAT). Loopback and link-local stay blocked. Overrides WEBHOOK_ALLOW_PRIVATE_NETWORK.', false, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'integration.webhook.allow-private-network');
